-- HostForge schema, part 1: extensions and shared helper functions.
--
-- Conventions (docs/ARCHITECTURE.md §5):
--   * every table has `id uuid primary key` (UUID v7, generated by the app; the
--     default below is only a fallback for ad-hoc SQL),
--   * `created_at timestamptz not null default now()`, `updated_at` where rows change
--     (kept current by the `set_updated_at` trigger attached by
--     `hf_attach_updated_at_triggers()`),
--   * statuses are `text` + `check` (values = hf-core `as_str()`), never PG enums,
--   * money is `numeric(20,6)` next to a `text` ISO 4217 code,
--   * tenant-owned tables have `tenant_id uuid not null references tenants(id) on delete cascade`
--     and indexes starting with `tenant_id`.
--
-- Requires PostgreSQL 15+ (`unique nulls not distinct`).

create extension if not exists citext;

-- UUID v7 generator: native `uuidv7()` on PostgreSQL 18+, a portable SQL version otherwise.
do $$
begin
    if to_regproc('pg_catalog.uuidv7') is not null then
        execute $f$
            create or replace function hf_uuid_v7() returns uuid
            language sql volatile parallel safe
            as 'select pg_catalog.uuidv7()'
        $f$;
    else
        execute $f$
            create or replace function hf_uuid_v7() returns uuid
            language sql volatile parallel safe
            as $body$
                select encode(
                    set_bit(
                        set_bit(
                            overlay(uuid_send(gen_random_uuid())
                                    placing substring(int8send(floor(extract(epoch from clock_timestamp()) * 1000)::bigint) from 3)
                                    from 1 for 6),
                            52, 1),
                        53, 1),
                    'hex')::uuid
            $body$
        $f$;
    end if;
end
$$;

-- Bumps `updated_at` when a row actually changes (no-op updates keep the old value,
-- which keeps idempotent seeds / upserts quiet).
create or replace function hf_set_updated_at() returns trigger
language plpgsql
as $$
begin
    if row(new.*) is distinct from row(old.*) then
        new.updated_at := now();
    end if;
    return new;
end
$$;

-- Attaches `set_updated_at` to every table of the current schema that has an
-- `updated_at` column and no such trigger yet. Each migration calls it at the end.
create or replace function hf_attach_updated_at_triggers() returns void
language plpgsql
as $$
declare
    r record;
begin
    for r in
        select c.table_schema, c.table_name
        from information_schema.columns c
        join information_schema.tables t
          on t.table_schema = c.table_schema
         and t.table_name = c.table_name
         and t.table_type = 'BASE TABLE'
        where c.table_schema = current_schema()
          and c.column_name = 'updated_at'
          and not exists (
              select 1
              from pg_trigger tg
              join pg_class cl on cl.oid = tg.tgrelid
              join pg_namespace n on n.oid = cl.relnamespace
              where n.nspname = c.table_schema
                and cl.relname = c.table_name
                and tg.tgname = 'set_updated_at'
          )
    loop
        execute format(
            'create trigger set_updated_at before update on %I.%I '
            'for each row execute function hf_set_updated_at()',
            r.table_schema, r.table_name
        );
    end loop;
end
$$;
